246	    /**
247	     * Build a {@code customerCode} of the form {@code <LAST3>-<NNNN>}: the upper-cased first
248	     * three letters of the owner's last name, a hyphen, and a global 4-digit zero-padded
249	     * sequence equal to one more than the current number of owners (e.g. {@code SMI-0007}).
250	     */
251	    private String generateCustomerCode(Owner owner) {
252	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
253	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
254	        int sequence = ownerRepository.findAll().size() + 1;
255	        return String.format("%s-%04d", last3, sequence);
256	    }
