265	    @Transactional(readOnly = true)
266	    public boolean isTelephoneInUse(String telephone) throws DataAccessException {
267	        String normalized = ownerMapper.normalizeTelephone(telephone);
268	        if (normalized == null) {
269	            return false;
270	        }
271	        return ownerRepository.findAll().stream()
272	            .map(existing -> ownerMapper.normalizeTelephone(existing.getTelephone()))
273	            .anyMatch(normalized::equals);
274	    }
