278	    public boolean isHouseholdInUse(String lastName, String address) throws DataAccessException {
279	        String normalizedLastName = normalizeHouseholdValue(lastName);
280	        String normalizedAddress = normalizeHouseholdValue(address);
281	        if (normalizedLastName == null || normalizedAddress == null) {
282	            return false;
283	        }
