@Override
@Transactional(readOnly = true)
public Collection<Vet> findVets() throws DataAccessException {
    return vetRepository.findAll();
}

@Override
@Transactional
public void saveOwner(Owner owner) throws DataAccessException {
    if (owner.getCustomerCode() == null) {
        owner.setCustomerCode(generateCustomerCode(owner));
    }
    ownerRepository.save(owner);

}

/**
 * Build a {@code customerCode} of the form {@code <LAST3>-<NNNN>}: the upper-cased first
 * three letters of the owner's last name, a hyphen, and a global 4-digit zero-padded
 * sequence equal to one more than the current number of owners (e.g. {@code SMI-0007}).
 */
private String generateCustomerCode(Owner owner) {
    String lastName = owner.getLastName() == null ? "" : owner.getLastName();
    String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
    int sequence = ownerRepository.findAll().size() + 1;
    return String.format("%s-%04d", last3, sequence);
}

@Override
@Transactional(readOnly = true)
public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
    return ownerRepository.findByLastName(lastName);
}

@Override
@Transactional(readOnly = true)
public boolean isTelephoneInUse(String telephone) throws DataAccessException {
    String normalized = ownerMapper.normalizeTelephone(telephone);
    if (normalized == null) {
        return false;
    }
    return ownerRepository.findAll().stream()
        .map(existing -> ownerMapper.normalizeTelephone(existing.getTelephone()))
        .anyMatch(normalized::equals);
}

@Override
@Transactional(readOnly = true)
public boolean isHouseholdInUse(String lastName, String address) throws DataAccessException {
    String normalizedLastName = normalizeHouseholdValue(lastName);
    String normalizedAddress = normalizeHouseholdValue(address);
    if (normalizedLastName == null || normalizedAddress == null) {
        return false;
    }
    return ownerRepository.findAll().stream()
        .anyMatch(existing -> normalizedLastName.equals(normalizeHouseholdValue(existing.getLastName()))
            && normalizedAddress.equals(normalizeHouseholdValue(existing.getAddress())));
}

/**
 * Canonicalize a last name or address for household comparison: trim, collapse every run of
 * whitespace to a single space and lower-case the result, so values that differ only in
 * letter case or incidental whitespace are treated as equal.
 */
private String normalizeHouseholdValue(String value) {
    if (value == null) {
        return null;
    }
    return value.trim().replaceAll("\\s+", " ").toLowerCase();
}

@Override
@Transactional(readOnly = true)
public Collection<Visit> findVisitsByPetId(int petId) {
    return visitRepository.findByPetId(petId);
}

@Override
@Transactional(readOnly = true)
public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
    return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
}

private <T> T findEntityById(Supplier<T> supplier) {
    try {
        return supplier.get();
    } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
        // Just ignore not found exceptions for Jdbc/Jpa realization
        return null;
    }

